#!/usr/bin/env node
// Plank join checker. Joins every @planks annotation to a current step-definition pattern,
// and carries the verification-conformance part of the join.
//
// Exits non-zero when:
//   - a behaviour-bearing production declaration carries no plank,
//   - a @planks string matches no current step-definition pattern,
//   - a @planks-provisional reference names no scenario that still carries @captain,
//   - a @planks token sits outside a docblock attached to a declaration,
//   - verification support breaks a rule in the verification-conformance rule set.

import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const acorn = require('acorn');

const ROOT = process.cwd();
const errors = [];
const notes = [];

function readRigging() {
  const text = fs.readFileSync(path.join(ROOT, 'RIGGING.md'), 'utf8');
  const values = {};
  for (const line of text.split('\n')) {
    const m = /^- ([A-Za-z-]+):\s*(.*)$/.exec(line.trim());
    if (!m) continue;
    const [, key, raw] = m;
    (values[key] ||= []).push(raw.trim());
  }
  return values;
}

function walk(dir, ext, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, ext, out);
    else if (entry.name.endsWith(ext)) out.push(full);
  }
  return out;
}

const rigging = readRigging();
const implementationDirs = (rigging.implementation || []).filter((d) => d !== 'none');
const specDirs = (rigging.specs || []).filter((d) => d !== 'none');
const verificationDirs = (rigging.verification || []).filter((d) => d !== 'none');
const scantlingPaths = (rigging.scantlings || []).filter((d) => d !== 'none');

// 1. Current step-definition patterns.
const stepFiles = verificationDirs.flatMap((d) => walk(path.join(ROOT, d), '.js'));
const patterns = new Set();
const patternFile = new Map();
for (const file of stepFiles) {
  const src = fs.readFileSync(file, 'utf8');
  const re = /\b(?:Given|When|Then)\s*\(\s*(['"`])((?:\\.|(?!\1)[^\\])*)\1/g;
  let m;
  while ((m = re.exec(src)) !== null) {
    patterns.add(m[2]);
    patternFile.set(m[2], path.relative(ROOT, file));
  }
}

// 2. Scenarios, and which of them still carry @captain.
const featureFiles = specDirs.flatMap((d) => walk(path.join(ROOT, d), '.feature'));
const captainScenarios = new Set();
const allScenarios = new Set();
const scenarioSteps = new Map();
for (const file of featureFiles) {
  const rel = path.relative(ROOT, file);
  const lines = fs.readFileSync(file, 'utf8').split('\n');
  let pendingTags = [];
  let current = null;
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith('@')) { pendingTags = trimmed.split(/\s+/); continue; }
    const scenario = /^Scenario(?: Outline)?:\s*(.+)$/.exec(trimmed);
    if (scenario) {
      current = `${rel}:${scenario[1].trim()}`;
      allScenarios.add(current);
      if (pendingTags.includes('@captain')) captainScenarios.add(current);
      pendingTags = [];
      scenarioSteps.set(current, []);
      continue;
    }
    const step = /^(Given|When|Then|And|But)\s+(.+)$/.exec(trimmed);
    if (step && current) scenarioSteps.get(current).push(step[2]);
    if (trimmed === '') pendingTags = [];
  }
}

// 3. Production seams and their planks, read from docblocks on declarations.
const PLANK = /@planks\(\s*"([^"]*)"\s*\)/g;
const PROVISIONAL = /@planks-provisional\(\s*"([^"]*)"\s*\)/g;
const join = [];
const implFiles = implementationDirs.flatMap((d) => walk(path.join(ROOT, d), '.js'));

for (const file of implFiles) {
  const rel = path.relative(ROOT, file);
  const src = fs.readFileSync(file, 'utf8');
  const comments = [];
  let ast;
  try {
    ast = acorn.parse(src, {
      ecmaVersion: 'latest',
      sourceType: src.includes('import ') || src.includes('export ') ? 'module' : 'script',
      locations: true,
      onComment: comments,
    });
  } catch (err) {
    errors.push(`${rel}: unparseable, ${err.message}`);
    continue;
  }

  const docblocks = comments.filter((c) => c.type === 'Block' && c.value.startsWith('*'));
  const claimedDocblocks = new Set();

  const declarations = [];
  const visit = (node, inClassBody = false) => {
    if (!node || typeof node.type !== 'string') return;
    if (
      node.type === 'FunctionDeclaration' ||
      node.type === 'ClassDeclaration' ||
      (node.type === 'MethodDefinition' && inClassBody) ||
      (node.type === 'VariableDeclaration' &&
        node.declarations.some((d) => d.init && /Function|ArrowFunctionExpression|ClassExpression/.test(d.init.type)))
    ) {
      declarations.push(node);
    }
    for (const key of Object.keys(node)) {
      const child = node[key];
      if (Array.isArray(child)) child.forEach((c) => visit(c, node.type === 'ClassBody'));
      else if (child && typeof child.type === 'string') visit(child, node.type === 'ClassBody');
    }
  };
  visit(ast);

  for (const decl of declarations) {
    const before = src.slice(0, decl.start);
    const doc = docblocks.find((c) => c.end <= decl.start && before.slice(c.end).trim() === '');
    const name =
      decl.id?.name ||
      decl.key?.name ||
      decl.declarations?.[0]?.id?.name ||
      '(anonymous)';
    const planks = [];
    const provisionals = [];
    if (doc) {
      claimedDocblocks.add(doc);
      let m;
      PLANK.lastIndex = 0;
      while ((m = PLANK.exec(doc.value)) !== null) planks.push(m[1]);
      PROVISIONAL.lastIndex = 0;
      while ((m = PROVISIONAL.exec(doc.value)) !== null) provisionals.push(m[1]);
    }
    const line = decl.loc.start.line;
    join.push({ file: rel, name, line, planks, provisionals });

    if (planks.length === 0 && provisionals.length === 0) {
      errors.push(`${rel}:${line}: seam "${name}" carries no plank`);
    }
    for (const plank of planks) {
      if (!patterns.has(plank)) {
        errors.push(`${rel}:${line}: plank "${plank}" matches no current step-definition pattern`);
      }
    }
    for (const ref of provisionals) {
      if (!captainScenarios.has(ref)) {
        errors.push(
          `${rel}:${line}: provisional plank "${ref}" names no scenario that still carries @captain`,
        );
      }
    }
  }

  // Plank form: every plank token in the file sits in a docblock attached to a declaration.
  const stray = [];
  for (const re of [/@planks\(/g, /@planks-provisional\(/g]) {
    let m;
    while ((m = re.exec(src)) !== null) {
      const inClaimed = [...claimedDocblocks].some((c) => m.index >= c.start && m.index <= c.end);
      if (!inClaimed) stray.push(src.slice(0, m.index).split('\n').length);
    }
  }
  for (const line of new Set(stray)) {
    errors.push(`${rel}:${line}: plank token outside a docblock attached to a declaration`);
  }
}

// 4. Orphaned step definitions: a pattern nothing plank names, reported as a note.
const plankStrings = new Set(join.flatMap((j) => j.planks));
for (const pattern of patterns) {
  if (!plankStrings.has(pattern)) notes.push(`step pattern with no plank: "${pattern}" (${patternFile.get(pattern)})`);
}

// 5. Scantling reference join: every scantlings path is named by at least one scenario.
const featureText = featureFiles.map((f) => fs.readFileSync(f, 'utf8')).join('\n');
for (const scantling of scantlingPaths) {
  const files = fs.existsSync(path.join(ROOT, scantling)) && fs.statSync(path.join(ROOT, scantling)).isDirectory()
    ? walk(path.join(ROOT, scantling), '.json').map((f) => path.relative(ROOT, f))
    : [scantling];
  for (const file of files) {
    if (!featureText.includes(file)) errors.push(`scantling "${file}" is referenced by no scenario`);
  }
}

// 6. Conformance part: the verification-conformance rule set over verification support.
const ruleSetPath = path.join(ROOT, 'scantlings', 'verification-conformance.json');
const conformance = [];
if (fs.existsSync(ruleSetPath)) {
  const ruleSet = JSON.parse(fs.readFileSync(ruleSetPath, 'utf8'));
  const supportFiles = verificationDirs.flatMap((d) => walk(path.join(ROOT, d), '.js'));
  for (const rule of ruleSet.rules) {
    const re = new RegExp(rule.forbid);
    for (const file of supportFiles) {
      const lines = fs.readFileSync(file, 'utf8').split('\n');
      lines.forEach((text, index) => {
        if (!re.test(text)) return;
        const window = lines.slice(Math.max(0, index - 5), index + 1).join('\n');
        if (rule.exempt && window.includes(rule.exempt)) return;
        conformance.push(`${path.relative(ROOT, file)}:${index + 1}: ${rule.id}, ${rule.description}`);
      });
    }
  }
} else {
  notes.push('verification-conformance rule set absent at scantlings/verification-conformance.json');
}

// Report.
console.log('# plank join');
console.log(`step-definition patterns: ${patterns.size}`);
console.log(`scenarios: ${allScenarios.size} (@captain: ${captainScenarios.size})`);
console.log(`production seams: ${join.length}`);
for (const seam of join) {
  const links = [...seam.planks.map((p) => `@planks "${p}"`), ...seam.provisionals.map((p) => `@planks-provisional "${p}"`)];
  console.log(`  ${seam.file}:${seam.line} ${seam.name} -> ${links.length ? links.join(', ') : 'UNPLANKED'}`);
}
console.log('\n# conformance');
if (conformance.length === 0) console.log('verification-conformance rule set: clean');
for (const finding of conformance) console.log(`  ${finding}`);
console.log('\n# notes');
for (const note of notes) console.log(`  ${note}`);
if (notes.length === 0) console.log('  none');

const failures = [...errors, ...conformance];
if (failures.length > 0) {
  console.error('\n# failures');
  for (const failure of failures) console.error(`  ${failure}`);
  process.exit(1);
}
console.log('\njoin clean');

{
  "description": "Verification-conformance rule set. Static rules over verification support that redden Verification-agreement breaches. Checked by the conformance part of the plank-join method.",
  "rules": [
    {
      "id": "no-guessed-delay",
      "description": "A wait ends on an observed signal, so a fixed-duration delay is a guess.",
      "forbid": "setTimeout\\s*\\(\\s*[^,]*,\\s*[0-9]+\\s*\\)",
      "exempt": "@exceptional-double"
    },
    {
      "id": "no-hand-built-page",
      "description": "Verification loads the real index.html, so an inline page string is a stand-in for the product.",
      "forbid": "innerHTML\\s*=\\s*['\"`]\\s*<(?:!doctype|html|section class=\"todoapp\")",
      "exempt": "@exceptional-double"
    },
    {
      "id": "no-unmarked-double",
      "description": "A stub, spy, fake, or mock carries the @exceptional-double mark with its justification.",
      "forbid": "\\b(sinon|jest\\.mock|createMock|createStub|fakeLocalStorage|stubStorage)\\b",
      "exempt": "@exceptional-double"
    },
    {
      "id": "no-per-scenario-rebuild-of-ambient-state",
      "description": "Ambient state a scenario never asserts is built once per run, not per scenario.",
      "forbid": "Before\\s*\\(\\s*(?:async\\s*)?function[^)]*\\)\\s*\\{[^}]*execSync",
      "exempt": "@exceptional-double"
    }
  ]
}

{
