import json,re,os
wb=json.load(open('watchbill.json'))
names={}
for f in os.listdir('features'):
    if f.endswith('.feature'):
        for l in open('features/'+f):
            m=re.match(r'\s*Scenario(?: Outline)?:\s*(.+)',l)
            if m: names.setdefault('features/'+f+':'+m.group(1).strip(),0)
bad=[]
for k,v in wb.items():
    assert re.fullmatch(r'watch\d+',k), k
